# =====================================================================
# Settings for the Emergency Ambulance web app. This file comes inside the frontend folder, so replacing the folder keeps working.
# If your Oracle password or anything below is different, do NOT edit this file (it is replaced with every new folder):
# put your own copy of this file as  config.py  NEXT TO the frontend folder (for example D:\config.py). That copy wins.
# =====================================================================
import os
import runpy

DB_USER = "SHREYA"                  # the schema of your workspace
DB_PASSWORD = ""                    # leave empty here: put your password in the config.py next to the frontend folder
DB_DSN = 'localhost:1521/XE'
ORACLE_CLIENT_DIR = None
USE_THICK_MODE = True
SECRET_KEY = "change-this-to-any-long-random-text"

# Oracle 11g needs the Oracle client libraries ("thick" mode); Python finds them by itself.
# If it cannot, set ORACLE_CLIENT_DIR to the folder that contains oci.dll, e.g. r"C:\oraclexe\app\oracle\product\11.2.0\server\bin"

_outside = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), "config.py")
if os.path.isfile(_outside):
    globals().update({k: v for k, v in runpy.run_path(_outside).items() if k.isupper()})

if not DB_PASSWORD:
    raise SystemExit("\nNo Oracle password yet. Create the file  %s  with these lines (type your own password):\n\n"
                     "    DB_USER = \"SHREYA\"\n    DB_PASSWORD = \"your-oracle-password\"\n    DB_DSN = \"localhost:1521/XE\"\n"
                     "\nIt sits next to the frontend folder, so replacing the frontend folder never removes it.\n" % _outside)
